1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound = errors.New("device not found")
12		ErrBatchConflict  = errors.New("batch conflicts with stored events")
13	)
14	
15	type Device struct {
16		ID            string             `json:"id"`
17		Site          string             `json:"site"`
18		RegisteredAt  time.Time          `json:"registeredAt"`
19		LastSeenAt    time.Time          `json:"lastSeenAt"`
20		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
21	}
22	
23	// Event is a single telemetry sample retained in a device's history.
24	type Event struct {
25		Sequence   int64              `json:"sequence"`
26		ObservedAt time.Time          `json:"observedAt"`
27		Values     map[string]float64 `json:"values"`
28	}
29	
30	// Sample is one replayed sample, decoded from the replay request body.
31	type Sample struct {
32		EventID    string
33		ObservedAt time.Time
34		Values     map[string]float64
35	}
36	
37	// ReplayReceipt summarises the outcome of a replay batch.
38	type ReplayReceipt struct {
39		BatchID      string         `json:"batchId"`
40		NewCount     int            `json:"newCount"`
41		Duplicate    int            `json:"duplicateCount"`
42		SampleStatus []SampleStatus `json:"samples"`
43	}
44	
45	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
46	type SampleStatus struct {
47		EventID   string `json:"eventId"`
48		Sequence  int64  `json:"sequence"`
49		Duplicate bool   `json:"duplicate"`
50	}
51	
52	// HistoryFilter narrows a history query by observed-time range. Zero times mean
53	// the bound is open.
54	type HistoryFilter struct {
55		From time.Time
56		To   time.Time
57	}
58	
59	// StoredBatch records the ordered samples an accepted batchId committed along
60	// with the receipt returned on first acceptance, so a repeated batchId can be
61	// checked for identical content and replayed with the original receipt.
62	type storedBatch struct {
63		samples []Sample
64		receipt ReplayReceipt
65	}
66	
67	type deviceState struct {
68		device  Device
69		events  []Event          // history ordered by sequence (sequence = index + 1)
70		byEvent map[string]int64 // eventId -> sequence
71		batches map[string]storedBatch
72	}
73	
74	type Store struct {
75		mu      sync.RWMutex
76		devices map[string]*deviceState
77		now     func() time.Time
78	
79		// wal is nil in memory mode. When set, every mutation is appended and
80		// synced here before in-memory state changes or success is returned.
81		wal walSink
82		iid []byte // data-directory instance id bound into history cursors
83	}
84	
85	func NewStore() *Store {
86		return &Store{devices: make(map[string]*deviceState), now: time.Now}
87	}
88	
89	// instanceID identifies the backing data directory; cursors are scoped to it.
90	// It is nil in memory mode.
91	func (s *Store) instanceID() []byte {
92		s.mu.RLock()
93		defer s.mu.RUnlock()
94		return s.iid
95	}
96	
97	// Exists reports whether a device is registered.
98	func (s *Store) Exists(id string) bool {
99		s.mu.RLock()
100		defer s.mu.RUnlock()
101		_, ok := s.devices[id]
102		return ok
103	}
104	
105	func (s *Store) Register(id, site string) (Device, bool, error) {
106		s.mu.Lock()
107		defer s.mu.Unlock()
108		if state, ok := s.devices[id]; ok {
109			return cloneDevice(state.device), false, nil
110		}
111		now := s.now().UTC()
112		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
113		if s.wal != nil {
114			if err := s.wal.appendRecord(recRegister, walRegister{
115				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
116			}); err != nil {
117				return Device{}, false, storageUnavailable(err)
118			}
119		}
120		s.devices[id] = &deviceState{
121			device:  device,
122			byEvent: make(map[string]int64),
123			batches: make(map[string]storedBatch),
124		}
125		return cloneDevice(device), true, nil
126	}
127	
128	// RecordTelemetry stores a live telemetry sample in the device history. The
129	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
130	// observed time is the server receive time.
131	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
132		s.mu.Lock()
133		defer s.mu.Unlock()
134		state, ok := s.devices[id]
135		if !ok {
136			return Device{}, ErrDeviceNotFound
137		}
138		now := s.now().UTC()
139		sequence := int64(len(state.events)) + 1
140		if s.wal != nil {
141			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
142				DeviceID:   id,
143				Sequence:   sequence,
144				ObservedAt: now,
145				Values:     values,
146			}); err != nil {
147				return Device{}, storageUnavailable(err)
148			}
149		}
150		state.events = append(state.events, Event{
151			Sequence:   sequence,
152			ObservedAt: now,
153			Values:     cloneTelemetry(values),
154		})
155		state.device.LastSeenAt = now
156		state.device.LastTelemetry = cloneTelemetry(values)
157		return cloneDevice(state.device), nil
158	}
159	
160	// Replay validates and commits a batch atomically. repeat is true when the
161	// batchId was already committed with identical content and the first receipt
162	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
163	// ErrBatchConflict when any sample clashes with an existing eventId or the
164	// batchId was previously committed with different ordered content; in either
165	// conflict case no state changes.
166	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
167		s.mu.Lock()
168		defer s.mu.Unlock()
169		state, ok := s.devices[id]
170		if !ok {
171			return ReplayReceipt{}, false, ErrDeviceNotFound
172		}
173	
174		if previous, exists := state.batches[batchID]; exists {
175			if !sameOrderedSamples(previous.samples, samples) {
176				return ReplayReceipt{}, false, ErrBatchConflict
177			}
178			return cloneReceipt(previous.receipt), true, nil
179		}
180	
181		// Validate every sample against committed history before appending so a
182		// conflict rolls back without leaving sequences, events or receipts.
183		type plan struct {
184			sample   Sample
185			sequence int64
186			dup      bool
187		}
188		planned := make([]plan, len(samples))
189		nextSequence := int64(len(state.events)) + 1
190		for i, sample := range samples {
191			if sequence, seen := state.byEvent[sample.EventID]; seen {
192				existing := state.events[sequence-1]
193				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
194					!sameValues(existing.Values, sample.Values) {
195					return ReplayReceipt{}, false, ErrBatchConflict
196				}
197				planned[i] = plan{sample, sequence, true}
198				continue
199			}
200			planned[i] = plan{sample, nextSequence, false}
201			nextSequence++
202		}
203	
204		// Build the receipt from the plan: only samples that matched a committed
205		// event before this batch are duplicates.
206		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
207		for _, entry := range planned {
208			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
209				EventID:   entry.sample.EventID,
210				Sequence:  entry.sequence,
211				Duplicate: entry.dup,
212			})
213			if entry.dup {
214				receipt.Duplicate++
215			} else {
216				receipt.NewCount++
217			}
218		}
219	
220		// Durable commit point: the whole batch is one record, synced before any
221		// in-memory state changes and before success is reported. A failure here
222		// leaves sequences, history, receipts and device state untouched.
223		lastNew := -1
224		for i, entry := range planned {
225			if !entry.dup {
226				lastNew = i
227			}
228		}
229		var committedAt time.Time
230		if s.wal != nil {
231			record := walReplay{
232				DeviceID: id,
233				BatchID:  batchID,
234				Samples:  make([]walSample, len(samples)),
235				Receipt:  receipt,
236			}
237			for i, sample := range samples {
238				record.Samples[i] = walSample{
239					EventID:    sample.EventID,
240					ObservedAt: sample.ObservedAt,
241					Values:     sample.Values,
242				}
243			}
244			if lastNew >= 0 {
245				committedAt = s.now().UTC()
246				record.LastSeenAt = &committedAt
247				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
248			}
249			if err := s.wal.appendRecord(recReplay, record); err != nil {
250				return ReplayReceipt{}, false, storageUnavailable(err)
251			}
252		}
253	
254		// Commit: append new samples in array order.
255		for _, entry := range planned {
256			if entry.dup {
257				continue
258			}
259			state.events = append(state.events, Event{
260				Sequence:   entry.sequence,
261				ObservedAt: entry.sample.ObservedAt,
262				Values:     cloneTelemetry(entry.sample.Values),
263			})
264			state.byEvent[entry.sample.EventID] = entry.sequence
265		}
266	
267		committed := make([]Sample, len(samples))
268		copy(committed, samples)
269		for i := range committed {
270			committed[i].Values = cloneTelemetry(samples[i].Values)
271		}
272		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
273	
274		if lastNew >= 0 {
275			if s.wal == nil {
276				committedAt = s.now().UTC()
277			}
278			state.device.LastSeenAt = committedAt
279			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
280		}
281		return receipt, false, nil
282	}
283	
284	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
285		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
286		return receipt
287	}
288	
289	// History returns one page of a device's event history. afterIndex is the first
290	// 0-based event slot to scan (0 for the first page); limit caps the number of
291	// matching events returned. bound pins the scan to sequences no larger than
292	// bound; a zero bound means "current maximum", which is then returned so
293	// callers can pin subsequent pages. nextIndex is the slot a following page
294	// should start at when hasMore is true. Concurrent writes therefore cannot
295	// skip or duplicate rows within a paged walk.
296	func (s *Store) History(id string, filter HistoryFilter, afterIndex, bound int64, limit int) (events []Event, appliedBound, nextIndex int64, hasMore bool, err error) {
297		s.mu.RLock()
298		defer s.mu.RUnlock()
299		state, ok := s.devices[id]
300		if !ok {
301			return nil, 0, 0, false, ErrDeviceNotFound
302		}
303		highWater := int64(len(state.events))
304		if bound == 0 {
305			bound = highWater
306		}
307		events = make([]Event, 0, limit)
308		for index := afterIndex; index < bound; index++ {
309			event := state.events[index]
310			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
311				continue
312			}
313			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
314				continue
315			}
316			if len(events) < limit {
317				events = append(events, cloneEvent(event))
318				continue
319			}
320			// This match belongs to the next page; resume scanning here so rows in
321			// the gap are never examined twice.
322			return events, bound, index, true, nil
323		}
324		return events, bound, bound, false, nil
325	}
326	
327	func (s *Store) Snapshot() []Device {
328		s.mu.RLock()
329		defer s.mu.RUnlock()
330		result := make([]Device, 0, len(s.devices))
331		for _, state := range s.devices {
332			result = append(result, cloneDevice(state.device))
333		}
334		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
335		return result
336	}
337	
338	func cloneDevice(device Device) Device {
339		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
340		return device
341	}
342	
343	func cloneEvent(event Event) Event {
344		event.Values = cloneTelemetry(event.Values)
345		return event
346	}
347	
348	func cloneTelemetry(values map[string]float64) map[string]float64 {
349		if values == nil {
350			return nil
351		}
352		cloned := make(map[string]float64, len(values))
353		for key, value := range values {
354			cloned[key] = value
355		}
356		return cloned
357	}
358	
359	// sameInstant compares times as UTC instants.
360	func sameInstant(a, b time.Time) bool {
361		return a.UTC().Equal(b.UTC())
362	}
363	
364	// sameValues compares metric maps by key and value.
365	func sameValues(a, b map[string]float64) bool {
366		if len(a) != len(b) {
367			return false
368		}
369		for key, value := range a {
370			other, ok := b[key]
371			if !ok || value != other {
372				return false
373			}
374		}
375		return true
376	}
377	
378	// sameOrderedSamples reports whether two batches carry the same samples in the
379	// same order, compared as UTC instants and key/value maps.
380	func sameOrderedSamples(a, b []Sample) bool {
381		if len(a) != len(b) {
382			return false
383		}
384		for i := range a {
385			if a[i].EventID != b[i].EventID ||
386				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
387				!sameValues(a[i].Values, b[i].Values) {
388				return false
389			}
390		}
391		return true
392	}
