632			tampered = "B" + tampered[1:]
633		} else {
634			tampered = "A" + tampered[1:]
635		}
636		if r := doRequest(t, h, http.MethodGet, "/v1/devices/a/history?limit=1&cursor="+tampered, ""); r.Code != http.StatusBadRequest {
637			t.Fatalf("tampered cursor status = %d, want 400", r.Code)
