275	func TestPersistentCorruptCommittedRecordFailsStartup(t *testing.T) {
276		dir := t.TempDir()
277		store := openPersistent(t, dir)
278		h := NewHandler(store)
279		mustRegister(t, h, "a")
280		mustRegister(t, h, "b")
281		mustRegister(t, h, "c")
282		if err := store.Close(); err != nil {
283			t.Fatal(err)
284		}
285	
286		raw := walRaw(t, dir)
287		// Locate the second committed frame (a register record) and flip a payload
288		// byte; its CRC then fails while later committed frames remain intact.
289		firstEnd := frameEnd(t, raw, headerLen)
290		secondPos := firstEnd
291		frameEnd(t, raw, secondPos) // sanity: the frame is fully present
292		target := secondPos + 5 + 2 // inside payload
293		original := raw[target]
294		raw[target] = original ^ 0xFF
295		if err := os.WriteFile(filepath.Join(dir, walName), raw, 0o600); err != nil {
296			t.Fatal(err)
297		}
298	
299		if _, err := NewPersistentStore(dir); err == nil {
300			t.Fatalf("startup succeeded with corrupt committed record")
301		} else if !strings.Contains(err.Error(), "corrupt") {
302			t.Fatalf("error = %v, want corruption message", err)
303		}
304	
305		// The damaged file is left exactly as found.
306		after := walRaw(t, dir)
307		if string(after) != string(raw) {
308			t.Fatalf("corrupt wal was modified by failed startup")
309		}
310	}
