337	// A bad CRC in a complete commit-journal block is committed-data damage; a
338	// short final block is an unacknowledged append and is trimmed.
339	func TestPersistentCommitJournalIntegrity(t *testing.T) {
340		dir := t.TempDir()
341		store := openPersistent(t, dir)
342		h := NewHandler(store)
343		mustRegister(t, h, "gw")
344		if err := store.Close(); err != nil {
345			t.Fatal(err)
346		}
347	
348		// Full final block with a flipped payload byte and invalid CRC -> fail.
349		goodJournal := commitRaw(t, dir)
350		journal := append([]byte(nil), goodJournal...)
351		journal[0] ^= 0xFF
352		journal[8] ^= 0xFF // keep the CRC invalid as well
353		if err := os.WriteFile(filepath.Join(dir, commitName), journal, 0o600); err != nil {
354			t.Fatal(err)
355		}
356		if _, err := NewPersistentStore(dir); err == nil || !strings.Contains(err.Error(), "commit journal") {
357			t.Fatalf("got %v, want commit journal corruption error", err)
358		}
359	
360		// Restore the good journal, then add a torn 5-byte tail: it must be
361		// trimmed without losing committed state.
362		if err := os.WriteFile(filepath.Join(dir, commitName), append(goodJournal, 1, 2, 3, 4, 5), 0o600); err != nil {
363			t.Fatal(err)
364		}
365		store3 := reopenPersistent(t, dir)
366		if !store3.Exists("gw") {
367			t.Fatalf("device lost while trimming torn journal tail")
368		}
369	}
