		alert.EndedAt = &t
	}
	if alert.AcknowledgedAt != nil {
		t := *alert.AcknowledgedAt
		alert.AcknowledgedAt = &t
	}
	return alert
}

func cloneAlerts(alerts []*Alert) []*Alert {
	if alerts == nil {
		return nil
	}
	cloned := make([]*Alert, len(alerts))
	for i, alert := range alerts {
		c := cloneAlert(*alert)
		cloned[i] = &c
	}
	return cloned
}

