	if alerts[0].TriggerSequence != 1 || alerts[0].TriggerValue != 40 ||
		alerts[0].RecoverSequence == nil || *alerts[0].RecoverSequence != 2 ||
		*alerts[0].RecoverValue != 20 {
		t.Fatalf("alert fields = %+v", alerts[0])
